"""Record actual emitted section/local-frame costs without inventing latency."""
from pathlib import Path
import hashlib,json,re
ROOT=Path(__file__).resolve().parents[1];RECEIPT='reviews/v5/expansion/legacy_advanced_timer/current_validation.json'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 d=json.loads((ROOT/RECEIPT).read_text());assert d['passed'];rows={r['label']:r for r in d['checks']};profiles=[]
 for cc in ['arm-none-eabi-gcc','clang']:
  for opt in ['-O0','-O3']:
   tag=cc+opt;r=rows[tag+' cost'];raw=(ROOT/r['raw']).read_text();sections=[]
   for name,size,address in re.findall(r'^(\S+)\s+(\d+)\s+(\d+)\s*$',raw,re.M):sections.append(dict(name=name,bytes=int(size),address=int(address)))
   stack=[]
   for path,h in d['outputs_sha256'].items():
    if '/'+tag+'/' in path and path.endswith('.su'):
     assert sha(ROOT/path)==h
     for line in (ROOT/path).read_text().splitlines():
      parts=line.split('\t')
      if len(parts)==3:stack.append(dict(function=parts[0].split(':')[-1],local_frame_bytes=int(parts[1]),kind=parts[2],source=path))
   assert stack and sections
   imports={unit:(ROOT/rows[tag+' '+unit+' imports']['raw']).read_text().strip().splitlines() for unit in ['core','target','clock','serial','firmware','helpers']}
   profiles.append(dict(profile=tag,sections=sections,local_stack_frames=stack,object_imports=imports,linked_imports=(ROOT/rows[tag+' image closure']['raw']).read_text(),helpers='Original assessor/execution/support.c; compiler-generated byte operations remain visible in imports/map. No compiler runtime archive.'))
 out=dict(passed=True,input_sha256={RECEIPT:sha(ROOT/RECEIPT),'tools/summarize_timer_costs.py':sha(Path(__file__))},profiles=profiles,comparison=dict(calculator='Bounded constant integer work, no allocation; explicit64-bit multiplies and validated32-bit division.',model='One input/counter event is O(1); test histories are bounded enumeration.',target='Fixed register sequence; capture is one bounded poll, not an acquisition queue or ISR latency bound.',measurement='Host-only exact rational interval analysis; not a target runtime dependency.'),limits=['Emitted section sizes and compiler local frames are observed; local frames are not complete call-chain/interrupt peak stack.','No physical waveform, skew, capture latency or energy measured.','Different optimization/targets require rebuilding; these are not portable golden costs.'])
 p=ROOT/'reviews/v5/expansion/legacy_advanced_timer/cost_analysis.json';p.write_text(json.dumps(out,indent=2)+'\n');print(dict(passed=True,profiles=len(profiles),local_frames=sum(len(p['local_stack_frames']) for p in profiles)))
if __name__=='__main__':main()
